<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {dateKey} from '../lib/action-insights.mjs'
import {studentApi} from '../api/student-capabilities'
import type {Semester} from '../api/backend-types'
import DetailPopover from './DetailPopover.vue'
import InfoSheet from './InfoSheet.vue'
const props=defineProps<{date:string}>()
const first=ref(''),weeks=ref(20),capacity=ref<number>(),periods=ref<{number:number;start:string;end:string}[]>([]),busy=ref(false),error=ref(''),status=ref(''),data=ref<Awaited<ReturnType<typeof studentApi.workload>>|null>(null)
const loading=ref(false),setupBusy=ref(true),setupReady=ref(false),timezone=ref('Asia/Shanghai')
const settingsOpen=ref(false)
let request=0
function formatConflict(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(date)}
onBeforeUnmount(()=>{request++})
async function load(){const current=++request;loading.value=true;error.value='';data.value=null;try{const anchor=new Date(props.date+'T12:00:00');anchor.setDate(anchor.getDate()-(anchor.getDay()+6)%7-7);const result=await studentApi.workload(dateKey(anchor.toISOString()));if(current===request)data.value=result}catch(e){if(current===request)error.value=(e as Error).message}finally{if(current===request)loading.value=false}}
async function setup(){setupBusy.value=true;error.value='';try{const s=await studentApi.semester();if(s){timezone.value=s.timezone??'Asia/Shanghai';first.value=s.first_monday;weeks.value=s.weeks??20;capacity.value=s.weekly_available_minutes??undefined;periods.value=s.periods}setupReady.value=true;await load()}catch(e){error.value=(e as Error).message}finally{setupBusy.value=false}}
async function save(){if(busy.value||!setupReady.value)return;error.value='';status.value='';if(new Date(first.value+'T12:00:00').getDay()!==1){error.value='第一教学周的起始日期请选择周一。';return}if(new Set(periods.value.map(p=>p.number)).size!==periods.value.length){error.value='节次编号不能重复，请核对后保存。';return}if(periods.value.some(p=>p.end<=p.start)){error.value='每一节的结束钟点须晚于开始钟点。';return}busy.value=true;try{const payload:Semester={first_monday:first.value,weeks:weeks.value,timezone:timezone.value,periods:periods.value,weekly_available_minutes:typeof capacity.value==='number'?capacity.value:null};await studentApi.saveSemester(payload);await load();status.value=error.value?'学期设置已保存，用时暂未刷新，请重新读取。':'学期设置已保存并重新计算。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(()=>props.date,load);onMounted(setup)
</script>
<template><section class="schedule-capacity" :aria-busy="loading||setupBusy"><div class="ws-section-head"><h2>三周用时与冲突</h2><button class="ws-text-button" @click="settingsOpen=true">设置学期时间</button></div><p v-if="loading||setupBusy" class="ws-muted" role="status">正在核对所选日期的用时…</p><p v-if="error" class="ws-field-error" role="alert">{{error}} <button class="ws-text-button" :disabled="loading||setupBusy||busy" @click="setupReady?load():setup()">重新读取</button></p><p v-if="data&&!data.configured" class="ws-muted">请先设置学期与节次钟点，再计算课程用时和时间冲突。</p><div v-if="data?.configured" class="capacity-weeks"><article v-for="w in data.weeks" :key="w.start"><time>{{w.start}} 起</time><strong>{{Math.round((w.course_minutes+w.task_minutes)/6)/10}} 小时</strong><span>课程 {{Math.round(w.course_minutes)}} 分钟 · 任务 {{Math.round(w.task_minutes)}} 分钟</span><span>{{w.remaining_minutes==null?'课外可用时间未填写':'课外剩余 '+Math.round(w.remaining_minutes)+' 分钟'}}</span></article></div><p class="ws-muted">{{data?.capacity_method}}</p><DetailPopover v-if="data?.conflicts.length" title="时间冲突" label="查看时间冲突" side="right"><template #trigger>{{data.conflicts.length}} 处时间重叠</template><ul><li v-for="(c,i) in data.conflicts" :key="i">{{c.first}} ↔ {{c.second}}<p>{{formatConflict(c.at)}}</p></li></ul></DetailPopover><p v-else-if="data?.configured">已提供的完整排期中未发现时间重叠。</p><DetailPopover v-if="data?.missing.length" title="尚未纳入计算的信息" label="查看待补充的时间信息" side="right"><template #trigger>{{data.missing.length}} 项时间信息待补充</template><ul><li v-for="m in data.missing" :key="m">{{m}}</li></ul></DetailPopover><InfoSheet :open="settingsOpen" shape="panel" title="学期与节次设置" description="填写学校真实节次钟点，用于计算课程用时和时间冲突。" @close="settingsOpen=false"><form class="semester-form" @submit.prevent="save"><fieldset :disabled="busy||setupBusy||!setupReady"><label class="ws-field">第一教学周的周一<input v-model="first" type="date" required/></label><label class="ws-field">教学周数<input v-model.number="weeks" type="number" min="1" max="53" required/></label><label class="ws-field">每周课外可用分钟<input v-model.number="capacity" type="number" min="0" max="10080"/></label><p class="ws-muted">请输入学校真实节次钟点，用时不会按一节课的固定分钟数猜算。</p><div v-for="(p,i) in periods" :key="i" class="period-row"><label>第<input v-model.number="p.number" type="number" min="1" max="30" required/>节</label><input v-model="p.start" type="time" aria-label="开始钟点" required/><input v-model="p.end" type="time" aria-label="结束钟点" required/><button type="button" class="btn" @click="periods.splice(i,1)">移除</button></div><button type="button" class="btn" @click="periods.push({number:Math.max(0,...periods.map(p=>p.number))+1,start:'',end:''})">添加节次</button><button class="btn btn--primary" :disabled="busy||!periods.length">{{busy?'正在保存…':'保存并计算'}}</button><p v-if="error" class="ws-field-error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p></fieldset><button v-if="!setupReady&&!setupBusy" type="button" class="btn" @click="setup">重新读取设置</button></form></InfoSheet></section></template>
<style scoped>.semester-form fieldset{display:grid;gap:14px;border:0;padding:0;margin:0;min-width:0}.schedule-capacity>.ws-section-head{flex-wrap:wrap;gap:12px}.period-row{padding:12px 0;border-bottom:1px solid var(--c-border)}.period-row input{min-height:40px;border:1px solid var(--c-border);border-radius:6px;background:var(--field-bg);color:var(--c-text)}.schedule-capacity{margin:24px 0}.semester-form{display:grid;gap:14px}.period-row{display:flex;gap:6px;flex-wrap:wrap}.period-row input[type=number]{width:50px}.capacity-weeks{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:20px 0}.capacity-weeks article{display:grid;gap:8px;padding-left:12px;border-left:3px solid var(--c-primary)}.capacity-weeks strong{font-size:24px;color:var(--c-primary)}.capacity-weeks span{font-size:12px;color:var(--c-text-3)}@media(max-width:650px){.capacity-weeks{grid-template-columns:1fr}}</style>
